script:
(function () {
  'use strict';
  // Student living budget (tuition not included). All amounts are monthly.
  //   Monthly income   = sum of income lines; monthly expenses = sum of expense lines
  //   Surplus (shortfall) = income - expenses; school-year totals = monthly x months in school
  //   Each expense's share = expense / total expenses
  // Verified (Node, scratch tests): default inputs give income $1,500, expenses $1,580,
  // shortfall $80 a month and $720 over 9 months; blank lines count as zero; all-zero input
  // shows $0 with no division by zero.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });

  var INCOME = [['sbJob', 'Job earnings'], ['sbFamily', 'Family support'], ['sbAid', 'Scholarships and grants'],
                ['sbLoans', 'Student loans'], ['sbOtherIncome', 'Other income']];
  var EXPENSES = [['sbRent', 'Rent or housing'], ['sbUtilities', 'Utilities and internet'], ['sbPhone', 'Phone'],
                  ['sbGroceries', 'Groceries'], ['sbDining', 'Eating out and coffee'], ['sbTransport', 'Transportation'],
                  ['sbBooks', 'Books and supplies'], ['sbHealth', 'Health and insurance'],
                  ['sbPersonal', 'Clothing and personal care'], ['sbFun', 'Entertainment and travel'],
                  ['sbSubs', 'Subscriptions'], ['sbDebt', 'Debt payments'], ['sbSaving', 'Savings'],
                  ['sbOther', 'Other expenses']];

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var s = String(el.value).trim();
    if (s === '') return 0; // a blank line counts as zero
    var v = parseFloat(s);
    return isNaN(v) ? NaN : v;
  }

  function summarize(income, expenses, months) {
    var inc = income.reduce(function (a, b) { return a + b; }, 0);
    var exp = expenses.reduce(function (a, b) { return a + b; }, 0);
    return { income: inc, expenses: exp, balance: inc - exp, yearIncome: inc * months,
             yearExpenses: exp * months, yearBalance: (inc - exp) * months,
             shares: expenses.map(function (e) { return exp > 0 ? e / exp : 0; }) };
  }

  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function signed(v) { return v < 0 ? '−' + money.format(-v) : money.format(v); }

  function update() {
    var income = INCOME.map(function (f) { return num(f[0]); });
    var expenses = EXPENSES.map(function (f) { return num(f[0]); });
    var months = Math.round(num('sbMonths'));
    var error = document.getElementById('sbError');
    var bad = income.concat(expenses).some(function (v) { return !isFinite(v) || v < 0 || v > 1e7; }) ||
              !(months >= 1 && months <= 12);
    error.hidden = !bad;
    if (bad) { error.textContent = 'Enter non-negative monthly amounts (leave a line blank for zero) and 1 to 12 months in the school year.'; return; }

    var r = summarize(income, expenses, months);
    setText('sbBalance', signed(r.balance));
    setText('sbBalanceLabel', r.balance < 0 ? 'Monthly shortfall' : 'Monthly money left over');
    setText('sbIncomeOut', money.format(r.income));
    setText('sbExpensesOut', money.format(r.expenses));
    setText('sbYearIncome', money.format(r.yearIncome));
    setText('sbYearExpenses', money.format(r.yearExpenses));
    setText('sbYearBalance', signed(r.yearBalance));
    setText('sbMonthsOut', String(months));
    setText('sbSpentShare', r.income > 0 ? pct.format(r.expenses / r.income) : '–');

    var rows = EXPENSES.map(function (f, i) { return { label: f[1], m: expenses[i], share: r.shares[i] }; })
      .filter(function (row) { return row.m > 0; })
      .sort(function (a, b) { return b.m - a.m; });
    var tbody = document.getElementById('sbTable');
    tbody.textContent = '';
    rows.concat([{ label: 'Total expenses', m: r.expenses, share: r.expenses > 0 ? 1 : 0, total: true }]).forEach(function (row) {
      var tr = document.createElement('tr');
      var th = document.createElement('th');
      th.scope = 'row';
      if (row.total) { var s = document.createElement('strong'); s.textContent = row.label; th.appendChild(s); }
      else th.textContent = row.label;
      tr.appendChild(th);
      [money.format(row.m), money.format(row.m * months), pct.format(row.share)].forEach(function (t) {
        var td = document.createElement('td'); td.textContent = t; tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });

    var notes = [];
    if (r.balance < 0) notes.push('Your expenses are ' + money.format(-r.balance) + ' a month more than your income, or ' +
      money.format(-r.yearBalance) + ' over ' + months + ' months. Look for costs to trim or extra income to close the gap.');
    else if (r.income > 0) notes.push('Your budget balances with ' + money.format(r.balance) + ' a month to spare, or ' +
      money.format(r.yearBalance) + ' over ' + months + ' months.');
    var loans = income[3];
    if (loans > 0 && r.income > 0) notes.push('Student loans cover ' + pct.format(loans / r.income) + ' of your monthly income; that money has to be repaid with interest.');
    var noteEl = document.getElementById('sbNote');
    noteEl.hidden = notes.length === 0;
    noteEl.className = 'callout ' + (r.balance < 0 ? 'callout-warning' : 'callout-note') + ' mt-4 text-sm';
    noteEl.textContent = notes.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('sbForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
